// Extrae el cuerpo de la petición
// n8n puede colocar el JSON en $json directamente o en $json.body
const raw = $input.first().json;
const body = (raw.body && typeof raw.body === 'object') ? raw.body : raw;

const message = (body.message || '').trim();
const sessionId = body.sessionId || ('session-' + Date.now());
const language  = body.language  || 'es';

if (!message) throw new Error('El campo message está vacío');

const systemPrompt = [
  'Eres OSS Advisor, un experto en herramientas de software open source (OSS).',
  'Cuando el usuario describa una necesidad técnica, recomienda las mejores librerías o proyectos OSS para resolverla.',
  '',
  'REGLAS:',
  '1. Responde ÚNICAMENTE con JSON válido — sin texto extra, sin bloques markdown, sin ```json.',
  '2. El JSON debe tener exactamente esta estructura:',
  '{',
  '  "reply": "texto de respuesta en español (2-3 oraciones, amigable y directo)",',
  '  "tools": [',
  '    {',
  '      "name": "Nombre de la herramienta",',
  '      "description": "Descripción breve en español (máx 90 caracteres)",',
  '      "repo": "https://github.com/owner/repo",',
  '      "tags": ["tag1", "tag2", "tag3"]',
  '    }',
  '  ]',
  '}',
  '3. Incluye entre 2 y 5 herramientas, ordenadas de más a menos recomendada.',
  '4. Solo incluye proyectos reales con repositorios reales en GitHub.',
  '5. Si la pregunta no es sobre tecnología o herramientas, responde igual con reply explicando que solo ayudas con OSS, y tools: [].',
].join('\n');

return [{ json: { message, sessionId, language, systemPrompt } }];

const resp = $input.first().json;

// Extraer el texto de la respuesta de OpenAI
// OpenAI devuelve: choices[0].message.content
// Con response_format: json_object, el contenido ya es JSON válido
let rawText = '';
try {
  rawText = resp.choices?.[0]?.message?.content || '';
} catch (e) {
  rawText = '';
}

let parsed;
try {
  parsed = JSON.parse(rawText);
} catch (e) {
  // Fallback: devolver el texto crudo como reply sin tools
  parsed = {
    reply: rawText || 'No pude generar una respuesta. Por favor reformulá tu pregunta.',
    tools: []
  };
}

// Sanitizar y normalizar la respuesta
const tools = Array.isArray(parsed.tools)
  ? parsed.tools.map(t => ({
      name:        String(t.name        || 'Herramienta'),
      description: String(t.description || ''),
      repo:        String(t.repo        || ''),
      tags:        Array.isArray(t.tags) ? t.tags.map(String) : []
    }))
  : [];

return [{ json: {
  reply: String(parsed.reply || ''),
  tools
}}];

// Rama de error: devuelve un mensaje amigable al frontend
const err = $input.first().json;
return [{ json: {
  reply: '❌ Error interno del servidor. Por favor intentá de nuevo en unos segundos.',
  tools: [],
  error: err.message || 'Unknown error'
}}];
